import {REVIEWED_WELCOME_UI} from './welcome.reviewed'
/** Current welcome-page UI only. No book text, catalog entries or user data. */
const keys=['الدخول كضيف','الدخول بحساب','رأس صفحة الخزانة','الخِزانة — الصفحة التعريفية','الخِزانة','الميزات','مكتبتك الإسلامية الذكية','كتابك كما طُبع، ومعرفتك أقرب إليك','الخِزانة تحفظ ملف Word الأصلي، وتعرض صفحاته بأمانة، وتجمع البحث والفهرسة والملاحظات والـPDF في تجربة قراءة عربية هادئة.','يعمل وضع الضيف على جهازك، ولا يرسل كتبك إلى حساب خارجي.','لماذا الخِزانة؟','أمانة النص وقوة البحث في مكان واحد','جميع كتب المكتبة الشاملة','تصفح الكتب ومؤلفيها وتصنيفاتها وفهارسها، وأضف كتبك الشخصية بصيغ Word وPDF وEPUB وBOK.','المصحف وخدمات التفسير','اقرأ بالرسم العثماني، وابحث في الآيات، واستفد من التفاسير والتلاوة الصوتية وخدمات القرآن.','السنة النبوية','تصفح مصادر الحديث وابحث في متونه، مع عرض التخريج والدرجة حين تتوفر بيانات موثقة.','قراءة وبحث بالعربية','فهرس قابل للبحث، وفلاتر للعناوين والمؤلفين، وانتقال إلى مواضع النتائج، مع خيارات الخط وسمات القراءة.','العلامات والملاحظات والتظليل','احفظ موضع القراءة والنصوص المظللة والملاحظات، وانسخ الفوائد مع توثيق الكتاب والمؤلف والصفحة.','تنظيم القراءة والبحث','رتب كتبك في رفوف، وأنشئ خطط قراءة ومشاريع بحثية، واحفظ اقتباساتك وراجع مقتطفاتك.','استعرض جميع الميزات وما يجري تطويره ←','المنصات المدعومة','تجربة واحدة للويب وسطح المكتب والجوال','تصفح الخزانة في Windows وAndroid وiPhone دون تغيير تجربة القراءة','المعرفة أقرب، والكتاب أوفى.','أنت تستخدم الخِزانة الآن كتطبيق مستقل.','تم قبول طلب التثبيت'] as const
const row=(text:string):Readonly<Record<string,string>>=>{const values=text.split('|');if(values.length!==keys.length)throw Error(`Welcome locale: ${values.length} values, expected ${keys.length}`);return Object.fromEntries(keys.map((key,i)=>[key,values[i]!]))}
